'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=file=>fs.readFileSync(path.join(root,file),'utf8');
const bootstrap=read('docs/scifi-ui/scripts/formatx-core-real3d-v20.js');
const src=read('docs/scifi-ui/scripts/formatx-reference-lock-v30.js');
const css=read('docs/scifi-ui/styles/formatx-reference-lock-v30.css');

assert.match(bootstrap,/reference-lock-v30/,'production bootstrap must select reference lock v30');
assert.match(bootstrap,/formatx-reference-lock-v30\.js\?v=20260810-uploaded-reference-lock-1/,'v30 renderer cache revision missing');
assert.match(bootstrap,/formatx-reference-lock-v30\.css\?v=20260810-uploaded-reference-lock-1/,'v30 styling cache revision missing');
assert.match(bootstrap,/fxCoreReal3d='ready-v20'/,'legacy ownership compatibility marker missing');
assert.match(bootstrap,/formatx:core3dfallback/,'bootstrap failure event missing');

assert.match(src,/const VERSION='v30-reference-lock'/,'v30 reference renderer marker missing');
assert.match(src,/canvas\.getContext\('webgl2'/,'native WebGL2 context missing');
assert.equal((src.match(/getContext\('webgl2'/g)||[]).length,1,'v30 must create exactly one WebGL2 context');
assert.match(src,/gl\.enable\(gl\.DEPTH_TEST\)/,'depth test missing');
assert.match(src,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangle rendering missing');
assert.match(src,/gl\.drawElements\(gl\.LINES/,'integrated 3D crystal line rendering missing');
assert.match(src,/function crystal\(/,'indexed four-sail crystal geometry missing');
assert.match(src,/function radius\(a\)/,'reference concave p-norm silhouette missing');
assert.match(src,/p=\.68/,'reference p-norm exponent missing');
assert.match(src,/1\.12\*/,'vertical reference stretch missing');
assert.match(src,/function torus\(/,'real 3D reactor/orbit torus geometry missing');
assert.match(src,/function sphere\(/,'real 3D moving core sphere missing');
assert.match(src,/const drift=/,'moving inner core missing');
assert.match(src,/const rs=\[\.20,\.29,\.39,\.51\]/,'four concentric reactor rings missing');
assert.match(src,/orbitSpecs|for\(const o of\[\[\.70/,'outer spectral orbit system missing');
assert.match(src,/cyan-violet-3d-v30/,'cyan/violet orbital state marker missing');
assert.match(src,/adaptive-60-plus-fps/,'adaptive performance target missing');
assert.match(src,/frameAverage|ema/,'measured frame-time adaptation missing');
assert.match(src,/pointermove/,'pointer-reactive 3D parallax missing');
assert.match(src,/prefers-reduced-motion/,'reduced-motion contract missing');
assert.match(src,/IntersectionObserver/,'renderer must pause outside hero');
assert.match(src,/webglcontextlost/,'context-loss handling missing');
assert.match(src,/fxCoreReferenceLock='ready-v30'/,'runtime reference lock marker missing');
assert.match(src,/fxCoreImageBacked='false'/,'non-image-backed runtime marker missing');
assert.doesNotMatch(src,/new\s+Image\s*\(|drawImage\s*\(|createImageBitmap\s*\(|backgroundImage/i,'MAG must not use raster imagery to fake 3D');
assert.doesNotMatch(src,/THREE\b|three\.js|babylon|playcanvas|model-viewer/i,'third-party scene engines are forbidden');
assert.doesNotMatch(src,/addEventListener\(['"](?:wheel|touchmove)['"][\s\S]{0,260}preventDefault/,'MAG must not capture page scrolling');
assert.match(css,/pointer-events:none/,'GPU stage must not intercept interaction');
assert.match(css,/100dvh/,'dynamic viewport sizing missing');
assert.match(css,/--fx-core-x:50%/,'portrait reference centering missing');
assert.match(css,/perspective\(560px\) rotateX\(63deg\)/,'reference perspective floor missing');
assert.match(css,/saturate\(1\.52\)/,'reference spectral grade missing');

console.log('PASS: production MAG v30 is a single-context indexed WebGL2 four-sail crystal locked to the uploaded reference, with a moving inner core, real 3D rings/orbits and adaptive 60+ FPS rendering.');
